-- 千问TTS预置 base_url 默认值 + 默认音色注入（音色管理弹窗数据源 ai_tts_voice）
-- 生成脚本：.workbuddy/gen_qwen_tts_seed.py（程序化生成，禁止手工改本文件数值）
-- base_url 实测 2026-10-06：compatible-mode/v1 拉模型列表 200；apps/anthropic 为 Anthropic 协议端点（LLM 用）
-- Python qwen_tts.py 合成走 maas.qianwenaiapi.com 原生端点，base_url 供控制台展示参考
-- 幂等：UPDATE 仅在 base_url 缺失时补；音色先 DELETE 后 INSERT

-- ===== provider 表单增加 base_url 字段（编辑对话框可见可改） =====
-- 仅追加缺失字段：先移除已存在的 base_url 条目再整体重写 fields，幂等
UPDATE `ai_model_provider`
SET `fields` = '[{"key":"api_key","label":"API密钥","type":"password"},{"key":"base_url","label":"服务地址","type":"string"},{"key":"model","label":"模型","type":"string"},{"key":"voice","label":"音色","type":"string"},{"key":"format","label":"音频格式","type":"string"},{"key":"sample_rate","label":"采样率","type":"number"},{"key":"instructions","label":"指令(可选)","type":"string"},{"key":"output_dir","label":"输出目录","type":"string"}]',
    `update_date` = NOW()
WHERE `id` = 'SYSTEM_TTS_qwen_tts'
  AND JSON_EXTRACT(`fields`, '$') NOT LIKE '%base_url%';

-- ===== base_url 补默认值（仅缺失时） =====
UPDATE `ai_model_config`
SET `config_json` = JSON_SET(`config_json`, '$.base_url', 'https://maas.qianwenaiapi.com/compatible-mode/v1'),
    `update_date` = NOW()
WHERE `id` = 'TTS_QwenTTS_Flash'
  AND JSON_EXTRACT(`config_json`, '$.base_url') IS NULL;

UPDATE `ai_model_config`
SET `config_json` = JSON_SET(`config_json`, '$.base_url', 'https://maas.qianwenaiapi.com/compatible-mode/v1'),
    `update_date` = NOW()
WHERE `id` = 'TTS_QwenTTS_Instruct'
  AND JSON_EXTRACT(`config_json`, '$.base_url') IS NULL;

UPDATE `ai_model_config`
SET `config_json` = JSON_SET(`config_json`, '$.base_url', 'https://maas.qianwenaiapi.com/compatible-mode/v1'),
    `update_date` = NOW()
WHERE `id` = 'TTS_QwenAudio_Flash'
  AND JSON_EXTRACT(`config_json`, '$.base_url') IS NULL;

UPDATE `ai_model_config`
SET `config_json` = JSON_SET(`config_json`, '$.base_url', 'https://maas.qianwenaiapi.com/compatible-mode/v1'),
    `update_date` = NOW()
WHERE `id` = 'TTS_QwenAudio_Plus'
  AND JSON_EXTRACT(`config_json`, '$.base_url') IS NULL;

